package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import com.primehr.shared.exception.IllegalLifecycleTransitionException;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;
@Entity @Table(name="rsp_stage_result") public class StageResult extends RspAuditedEntity{
 public enum Status{DRAFT,RETURNED,SUBMITTED,VALIDATED,SUPERSEDED}public enum GateOutcome{PASS,FAIL,NOT_APPLICABLE}
 @Column(name="proceeding_id",nullable=false,length=36)private String proceedingId;@Column(name="session_id",length=36)private String sessionId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="stage_id",nullable=false,length=36)private String stageId;@Column(name="result_revision",nullable=false)private int resultRevision;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="current_result_key",length=200)private String currentResultKey;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private Status status;@Column(name="raw_score",precision=12,scale=4)private BigDecimal rawScore;@Column(name="maximum_score",precision=12,scale=4)private BigDecimal maximumScore;@Column(name="normalized_score",precision=12,scale=4)private BigDecimal normalizedScore;@Enumerated(EnumType.STRING)@Column(name="gate_outcome",length=20)private GateOutcome gateOutcome;@Column(length=2000)private String remarks;@Column(name="evidence_required",nullable=false)private boolean evidenceRequired;@Column(name="recorded_by",nullable=false,length=100)private String recordedBy;@Column(name="submitted_by",length=100)private String submittedBy;@Column(name="submitted_at")private Instant submittedAt;@Column(name="validated_by",length=100)private String validatedBy;@Column(name="validated_at")private Instant validatedAt;@Column(name="returned_by",length=100)private String returnedBy;@Column(name="returned_at")private Instant returnedAt;@Column(name="return_reason",length=2000)private String returnReason;
 protected StageResult(){}public StageResult(String agency,String proceeding,String session,String candidate,String stage,int revision,String prior,boolean evidence,String actor){super(agency);proceedingId=requiredText(proceeding,"proceedingId");sessionId=optionalText(session);candidateId=requiredText(candidate,"candidateId");stageId=requiredText(stage,"stageId");if(revision<1)throw new IllegalArgumentException("resultRevision must be positive");resultRevision=revision;supersedesId=optionalText(prior);currentResultKey=proceedingId+":"+candidateId+":"+stageId;status=Status.DRAFT;evidenceRequired=evidence;recordedBy=requiredText(actor,"actor");}
 public void recordScore(BigDecimal raw,BigDecimal max,int scale,RoundingMode rounding,String remarks){editable();if(raw==null||max==null||raw.signum()<0||max.signum()<=0||raw.compareTo(max)>0)throw new IllegalArgumentException("Score is outside the configured bounds");rawScore=raw;maximumScore=max;normalizedScore=raw.multiply(new BigDecimal("100")).divide(max,scale,rounding);gateOutcome=null;this.remarks=optionalText(remarks);}
 public void recordGate(GateOutcome outcome,String remarks){editable();gateOutcome=Objects.requireNonNull(outcome);rawScore=null;maximumScore=null;normalizedScore=null;this.remarks=optionalText(remarks);}
 public void submit(String actor,Instant at){editable();if(normalizedScore==null&&gateOutcome==null)throw new IllegalLifecycleTransitionException("A result cannot be submitted without an outcome");submittedBy=requiredText(actor,"actor");if(!recordedBy.equalsIgnoreCase(submittedBy))throw new IllegalLifecycleTransitionException("Only the recorder may submit this result");submittedAt=Objects.requireNonNull(at);status=Status.SUBMITTED;returnedBy=null;returnedAt=null;returnReason=null;}
 public void validate(String actor,Instant at){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only a SUBMITTED result may be validated");String validator=requiredText(actor,"actor");if(recordedBy.equalsIgnoreCase(validator))throw new IllegalLifecycleTransitionException("The result recorder cannot validate the same result");validatedBy=validator;validatedAt=Objects.requireNonNull(at);status=Status.VALIDATED;}
 public void returnForCorrection(String actor,String reason,Instant at){if(status!=Status.SUBMITTED)throw new IllegalLifecycleTransitionException("Only a SUBMITTED result may be returned");String validator=requiredText(actor,"actor");if(recordedBy.equalsIgnoreCase(validator))throw new IllegalLifecycleTransitionException("The result recorder cannot return their own result");returnedBy=validator;returnReason=requiredText(reason,"reason");returnedAt=Objects.requireNonNull(at);status=Status.RETURNED;}
 public void supersede(){if(status!=Status.VALIDATED)throw new IllegalLifecycleTransitionException("Only a VALIDATED result may be superseded");currentResultKey=null;status=Status.SUPERSEDED;}private void editable(){if(status!=Status.DRAFT&&status!=Status.RETURNED)throw new IllegalLifecycleTransitionException("Only a DRAFT or RETURNED result may be edited");}
 public String getProceedingId(){return proceedingId;}public String getSessionId(){return sessionId;}public String getCandidateId(){return candidateId;}public String getStageId(){return stageId;}public int getResultRevision(){return resultRevision;}public String getSupersedesId(){return supersedesId;}public Status getStatus(){return status;}public BigDecimal getRawScore(){return rawScore;}public BigDecimal getMaximumScore(){return maximumScore;}public BigDecimal getNormalizedScore(){return normalizedScore;}public GateOutcome getGateOutcome(){return gateOutcome;}public String getRemarks(){return remarks;}public boolean isEvidenceRequired(){return evidenceRequired;}public String getRecordedBy(){return recordedBy;}public String getSubmittedBy(){return submittedBy;}public String getValidatedBy(){return validatedBy;}public Instant getValidatedAt(){return validatedAt;}public String getReturnReason(){return returnReason;}
}
